import sympy

def build_instance(rng):
    first_term = rng.randint(1, 10)
    common_ratio = rng.randint(1, 10)
    term_count = rng.randint(2, 5)
    sum_formula = first_term * (1 - common_ratio ** term_count) / (1 - common_ratio)
    sum_value = sum_formula
    answer = str(sum_value)
    x = sympy.symbols('x')
    geometric_series = first_term * common_ratio ** x
    symbolic_sum = sympy.summation(geometric_series, (x, 0, term_count - 1))
    check_value = symbolic_sum
    check = str(check_value)
    parameters = {'first_term': first_term, 'common_ratio': common_ratio, 'term_count': term_count}
    return (parameters, answer, check)



